for it in "${items[@]}"; do
  IFS='|' read -r aspect bg dir name prompt <<< "$it"
  echo "=== $name ==="
  $API general-image-run \
    --generation-model image-2.5 --aspect-ratio "$aspect" --resolution 1K \
    --quality standard --remove-bg-method "$bg" \
    --output-dir "assets/raw_final/${dir}/${name}" \
    --prompt "$prompt" 2>&1 | grep -E '"status"|credit_cost|"error"'
  echo ""
done
echo "ALL FINAL DONE"
